{
  "name": "Dr. Gemini - AI Medical Assistant",
  "description": "An advanced AI-powered medical assistant that provides health consultations, finds nearby medical services, and researches the latest medical information.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ChatMode {
  CONSULTATION = 'CONSULTATION', // gemini-3-pro-preview (Thinking)
  FIND_CARE = 'FIND_CARE',       // gemini-2.5-flash (Maps)
  RESEARCH = 'RESEARCH'          // gemini-2.5-flash (Search)
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
  mode: ChatMode;
  isThinking?: boolean; // For UI state while streaming thinking
  groundingMetadata?: GroundingMetadata;
}

export interface GroundingMetadata {
  searchChunks?: {
    uri: string;
    title: string;
  }[];
  mapChunks?: {
    source: {
        uri: string;
    };
    placeId: string;
    title: string;
  }[];
}

export interface UserLocation {
  latitude: number;
  longitude: number;
}

import { ChatMode } from "./types";
import { Stethoscope, MapPin, Search } from "lucide-react";

export const CHAT_MODES = [
  {
    id: ChatMode.CONSULTATION,
    label: "Medical Consultation",
    description: "Deep reasoning for diagnosis & advice",
    icon: Stethoscope,
    color: "text-blue-600",
    bg: "bg-blue-100",
    border: "border-blue-200"
  },
  {
    id: ChatMode.FIND_CARE,
    label: "Find Nearby Care",
    description: "Locate doctors, clinics & pharmacies",
    icon: MapPin,
    color: "text-emerald-600",
    bg: "bg-emerald-100",
    border: "border-emerald-200"
  },
  {
    id: ChatMode.RESEARCH,
    label: "Medical Research",
    description: "Search latest medical news & data",
    icon: Search,
    color: "text-violet-600",
    bg: "bg-violet-100",
    border: "border-violet-200"
  }
];

export const DISCLAIMER_TEXT = `
I am an AI assistant, not a human doctor. 
My responses are for informational purposes only and should not replace professional medical advice, diagnosis, or treatment. 
If you are experiencing a medical emergency, please call emergency services immediately.
`;

import { GoogleGenAI, Type } from "@google/genai";
import { ChatMode, UserLocation } from "../types";

// Initialize the client with the API key from the environment
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION_CONSULTATION = `
You are Dr. Gemini, a highly intelligent, empathetic, and professional medical AI assistant.
Your goal is to act like a knowledgeable doctor:
1. Listen carefully to the user's symptoms or health concerns.
2. Ask clarifying questions if necessary to narrow down the issue.
3. Provide potential explanations (differential diagnosis) in clear, accessible language.
4. Suggest practical solutions, including lifestyle changes, home remedies, and over-the-counter medications where appropriate.
5. ALWAYS maintain a calm, reassuring tone.

CRITICAL SAFETY RULES:
- You MUST explicitly state that you are an AI and not a substitute for professional medical advice.
- If the user describes life-threatening symptoms (e.g., severe chest pain, trouble breathing, signs of stroke, severe bleeding), IMMEDIATELY advise them to call emergency services or go to the nearest ER.
- Do not make definitive diagnoses (e.g., "You have cancer"). Instead, use phrasing like "This could be consistent with..." or "Possible causes include...".
`;

const SYSTEM_INSTRUCTION_MAPS = `
You are a medical location assistant. Your primary job is to help the user find medical facilities, doctors, pharmacies, or specialists nearby using Google Maps.
Be concise and helpful. Extract the location data and present it clearly.
`;

const SYSTEM_INSTRUCTION_SEARCH = `
You are a medical research assistant. Use Google Search to find the most up-to-date information on diseases, treatments, drugs, and medical news.
Synthesize the information clearly and cite your sources if possible.
`;

interface GenerateResponseParams {
  prompt: string;
  history: { role: string; parts: { text: string }[] }[];
  mode: ChatMode;
  location?: UserLocation;
}

export const generateResponse = async ({
  prompt,
  history,
  mode,
  location,
}: GenerateResponseParams) => {

  // Convert history to the format expected by the SDK (although we are using single-turn for some tools, chat is better for context)
  // Note: For this implementation, we will treat each "mode" as a fresh context or use chat if supported.
  // To keep it simple and robust, we will use `sendMessage` on a chat session for Consultation, 
  // and `generateContent` for Maps/Search to ensure specific tool config is applied correctly per turn without context pollution.
  // Ideally, we'd maintain separate chat sessions, but for this demo, we'll try to maintain a unified history if possible,
  // or just pass the relevant context.

  // Simplified Approach: Pass the last few messages as context string if using generateContent, or use chat for Consultation.

  let systemInstruction = SYSTEM_INSTRUCTION_CONSULTATION;
  let modelName = 'gemini-3-pro-preview';
  let tools: any[] = [];
  let toolConfig: any = undefined;
  let thinkingConfig: any = undefined;

  // Configure based on Mode
  switch (mode) {
    case ChatMode.CONSULTATION:
      modelName = 'gemini-3-pro-preview';
      systemInstruction = SYSTEM_INSTRUCTION_CONSULTATION;
      // Enable Thinking for complex medical reasoning
      thinkingConfig = { thinkingBudget: 32768 }; 
      break;

    case ChatMode.FIND_CARE:
      modelName = 'gemini-2.5-flash';
      systemInstruction = SYSTEM_INSTRUCTION_MAPS;
      tools = [{ googleMaps: {} }];
      if (location) {
        toolConfig = {
          retrievalConfig: {
            latLng: {
              latitude: location.latitude,
              longitude: location.longitude,
            },
          },
        };
      }
      break;

    case ChatMode.RESEARCH:
      modelName = 'gemini-2.5-flash';
      systemInstruction = SYSTEM_INSTRUCTION_SEARCH;
      tools = [{ googleSearch: {} }];
      break;
  }

  // Construct the full context from history for the prompt if using generateContent
  // For ChatMode.CONSULTATION, we want a real chat session for multi-turn reasoning.

  try {
    if (mode === ChatMode.CONSULTATION) {
       // Using Chat API for Consultation to keep context
       // We map our history to the SDK Chat format
       const chatHistory = history.map(h => ({
         role: h.role,
         parts: h.parts
       }));

       const chat = ai.chats.create({
         model: modelName,
         config: {
           systemInstruction,
           thinkingConfig,
         },
         history: chatHistory
       });

       const result = await chat.sendMessage({ message: prompt });
       return {
         text: result.text,
         groundingMetadata: undefined // 3-pro-preview doesn't typically return grounding chunks in the same way as flash tools yet
       };

    } else {
      // For Maps and Search, we use generateContent (stateless per turn, but we inject context)
      // This ensures the specific tool (Maps/Search) is triggered reliably.

      const previousContext = history.map(h => `${h.role}: ${h.parts[0].text}`).join('\n');
      const fullPrompt = `Context of conversation:\n${previousContext}\n\nCurrent User Request: ${prompt}`;

      const result = await ai.models.generateContent({
        model: modelName,
        contents: fullPrompt,
        config: {
          systemInstruction,
          tools,
          toolConfig,
        }
      });

      // Extract text
      const text = result.text;

      // Extract grounding metadata if available
      const groundingMetadata = result.candidates?.[0]?.groundingMetadata;

      let parsedGrounding: any = {};

      if (groundingMetadata?.groundingChunks) {
         // Map grounding
         const mapChunks = groundingMetadata.groundingChunks
           .filter((c: any) => c.web?.uri && c.web?.title) // Search usually returns web
           .map((c: any) => ({ uri: c.web.uri, title: c.web.title }));

         // Search grounding (sometimes structured differently)
         // The SDK types for chunks can be diverse. We try to grab what we can.
         // For Maps, we look for place/maps specific data if available in raw response, 
         // but usually it is embedded in the text or standard grounding chunks.
         // Let's rely on the text for the main content and use chunks for links.

         parsedGrounding.searchChunks = mapChunks; // Reusing structure
      }

      return {
        text,
        groundingMetadata: parsedGrounding
      };
    }
  } catch (error) {
    console.error("Gemini API Error:", error);
    return {
      text: "I apologize, but I encountered an error processing your request. Please try again.",
      groundingMetadata: undefined
    };
  }
};

import React, { useState, KeyboardEvent } from 'react';
import { Send, Sparkles } from 'lucide-react';
import { ChatMode } from '../types';

interface ChatInputProps {
  onSendMessage: (text: string) => void;
  isLoading: boolean;
  activeMode: ChatMode;
}

export const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading, activeMode }) => {
  const [input, setInput] = useState('');

  const handleSend = () => {
    if (input.trim() && !isLoading) {
      onSendMessage(input);
      setInput('');
    }
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="bg-white border-t border-slate-200 p-4 pb-6">
      <div className="max-w-4xl mx-auto flex items-center gap-3">
        <div className="relative flex-1">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={
                activeMode === ChatMode.CONSULTATION ? "Describe your symptoms..." :
                activeMode === ChatMode.FIND_CARE ? "Find a clinic near..." :
                "Search for medical info..."
            }
            className={`w-full pl-5 pr-12 py-4 rounded-2xl bg-slate-50 border-2 border-slate-200 focus:outline-none focus:border-blue-400 focus:ring-2 focus:ring-blue-100 transition-all text-slate-700 placeholder-slate-400 ${isLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
            disabled={isLoading}
          />
          <div className="absolute right-3 top-1/2 -translate-y-1/2">
             {isLoading ? (
                 <div className="flex gap-1 p-2">
                     <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0s' }}></span>
                     <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></span>
                     <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></span>
                 </div>
             ) : (
                <Sparkles className="w-5 h-5 text-slate-300" />
             )}
          </div>
        </div>
        <button
          onClick={handleSend}
          disabled={!input.trim() || isLoading}
          className={`p-4 rounded-2xl transition-all duration-300 shadow-lg ${
            !input.trim() || isLoading
              ? 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'
              : 'bg-gradient-to-br from-blue-600 to-indigo-600 text-white hover:shadow-blue-200 hover:scale-105 active:scale-95'
          }`}
        >
          <Send className="w-5 h-5" />
        </button>
      </div>
      <div className="max-w-4xl mx-auto mt-2 text-center">
        <p className="text-xs text-slate-400">
           Dr. Gemini may produce inaccurate information. Always verify with a professional.
        </p>
      </div>
    </div>
  );
};

import React from 'react';
import ReactMarkdown from 'react-markdown';
import { User, Bot, BrainCircuit, Map, ExternalLink } from 'lucide-react';
import { Message, ChatMode } from '../types';

interface MessageBubbleProps {
  message: Message;
}

export const MessageBubble: React.FC<MessageBubbleProps> = ({ message }) => {
  const isUser = message.role === 'user';

  // Helper to determine border color based on mode for AI messages
  const getModeStyles = () => {
    if (isUser) return 'bg-blue-600 text-white rounded-br-none';

    switch (message.mode) {
      case ChatMode.CONSULTATION:
        return 'bg-white border border-slate-200 text-slate-800 rounded-bl-none shadow-sm';
      case ChatMode.FIND_CARE:
        return 'bg-emerald-50 border border-emerald-100 text-slate-800 rounded-bl-none shadow-sm';
      case ChatMode.RESEARCH:
        return 'bg-violet-50 border border-violet-100 text-slate-800 rounded-bl-none shadow-sm';
      default:
        return 'bg-white border-slate-200';
    }
  };

  const ModeIcon = () => {
    if (isUser) return <User className="w-5 h-5 text-blue-100" />;
    switch (message.mode) {
        case ChatMode.CONSULTATION: return <Bot className="w-6 h-6 text-blue-600" />;
        case ChatMode.FIND_CARE: return <Map className="w-6 h-6 text-emerald-600" />;
        case ChatMode.RESEARCH: return <BrainCircuit className="w-6 h-6 text-violet-600" />;
    }
    return <Bot />;
  };

  return (
    <div className={`flex w-full mb-6 ${isUser ? 'justify-end' : 'justify-start'}`}>
      <div className={`flex max-w-[85%] md:max-w-[75%] gap-3 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className={`flex-shrink-0 w-10 h-10 rounded-full flex items-center justify-center shadow-sm ${isUser ? 'bg-blue-700' : 'bg-white border border-slate-100'}`}>
          <ModeIcon />
        </div>

        {/* Bubble */}
        <div className={`flex flex-col gap-2`}>
            {/* Thinking Indicator State */}
            {message.isThinking && !isUser && (
                <div className="flex items-center gap-2 text-xs font-medium text-amber-600 bg-amber-50 px-3 py-1 rounded-full w-fit border border-amber-100 animate-pulse mb-1">
                    <BrainCircuit className="w-3 h-3" />
                    <span>Thinking...</span>
                </div>
            )}

            <div className={`p-5 rounded-2xl ${getModeStyles()} text-sm md:text-base leading-relaxed`}>
            <ReactMarkdown 
                components={{
                    ul: ({node, ...props}) => <ul className="list-disc ml-4 my-2 space-y-1" {...props} />,
                    ol: ({node, ...props}) => <ol className="list-decimal ml-4 my-2 space-y-1" {...props} />,
                    strong: ({node, ...props}) => <strong className="font-semibold" {...props} />,
                    p: ({node, ...props}) => <p className="mb-2 last:mb-0" {...props} />,
                    a: ({node, ...props}) => <a className="text-blue-600 underline hover:text-blue-800" target="_blank" rel="noopener noreferrer" {...props} />,
                }}
            >
                {message.text}
            </ReactMarkdown>
            </div>

            {/* Sources / Grounding */}
            {!isUser && message.groundingMetadata?.searchChunks && message.groundingMetadata.searchChunks.length > 0 && (
                <div className="mt-1 flex flex-wrap gap-2">
                    {message.groundingMetadata.searchChunks.map((chunk, idx) => (
                        <a 
                            key={idx} 
                            href={chunk.uri}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-xs text-slate-500 hover:text-blue-600 hover:border-blue-200 transition-colors shadow-sm"
                        >
                            <ExternalLink className="w-3 h-3" />
                            <span className="truncate max-w-[150px]">{chunk.title || chunk.uri}</span>
                        </a>
                    ))}
                </div>
            )}

            {/* Timestamp */}
            <span className={`text-[10px] text-slate-400 font-medium mt-1 px-1 ${isUser ? 'text-right' : 'text-left'}`}>
                {message.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </span>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { CHAT_MODES } from '../constants';
import { ChatMode } from '../types';

interface ModeSelectorProps {
  currentMode: ChatMode;
  onModeChange: (mode: ChatMode) => void;
  disabled: boolean;
}

export const ModeSelector: React.FC<ModeSelectorProps> = ({ currentMode, onModeChange, disabled }) => {
  return (
    <div className="w-full bg-white border-b border-slate-200 px-4 py-3 sticky top-0 z-10 shadow-sm">
      <div className="max-w-4xl mx-auto">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
          {CHAT_MODES.map((mode) => {
            const Icon = mode.icon;
            const isActive = currentMode === mode.id;
            return (
              <button
                key={mode.id}
                onClick={() => onModeChange(mode.id)}
                disabled={disabled}
                className={`flex items-center gap-3 p-3 rounded-xl border transition-all duration-200 text-left ${
                  isActive
                    ? `${mode.bg} ${mode.border} ring-1 ring-offset-1 ring-blue-100`
                    : 'bg-white border-slate-100 hover:border-slate-300 hover:bg-slate-50'
                } ${disabled ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <div className={`p-2 rounded-lg ${isActive ? 'bg-white/60' : 'bg-slate-100'} ${mode.color}`}>
                  <Icon className="w-5 h-5" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className={`font-semibold text-sm ${isActive ? 'text-slate-900' : 'text-slate-700'}`}>
                    {mode.label}
                  </div>
                  <div className="text-xs text-slate-500 truncate">
                    {mode.description}
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { AlertTriangle, Check } from 'lucide-react';
import { DISCLAIMER_TEXT } from '../constants';

interface DisclaimerModalProps {
  onAccept: () => void;
}

export const DisclaimerModal: React.FC<DisclaimerModalProps> = ({ onAccept }) => {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4">
      <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 animate-in fade-in zoom-in duration-300 border border-slate-200">
        <div className="flex flex-col items-center text-center gap-4">
          <div className="w-16 h-16 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center">
            <AlertTriangle className="w-8 h-8" />
          </div>

          <h2 className="text-2xl font-bold text-slate-800">Important Medical Disclaimer</h2>

          <div className="bg-slate-50 p-4 rounded-xl border border-slate-100 text-slate-600 text-sm leading-relaxed text-left">
             {DISCLAIMER_TEXT}
          </div>

          <button
            onClick={onAccept}
            className="w-full mt-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3.5 px-6 rounded-xl flex items-center justify-center gap-2 transition-all active:scale-95"
          >
            <Check className="w-5 h-5" />
            I Understand & Agree
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ChatInput } from './components/ChatInput';
import { MessageBubble } from './components/MessageBubble';
import { ModeSelector } from './components/ModeSelector';
import { DisclaimerModal } from './components/DisclaimerModal';
import { generateResponse } from './services/geminiService';
import { ChatMode, Message, UserLocation } from './types';
import { Activity } from 'lucide-react';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [currentMode, setCurrentMode] = useState<ChatMode>(ChatMode.CONSULTATION);
  const [hasAcceptedDisclaimer, setHasAcceptedDisclaimer] = useState(false);
  const [userLocation, setUserLocation] = useState<UserLocation | undefined>(undefined);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Get location on mount (helpful for map features)
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setUserLocation({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
          });
        },
        (error) => {
          console.log("Location access denied or error:", error);
        }
      );
    }
  }, []);

  const handleSendMessage = async (text: string) => {
    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      text,
      timestamp: new Date(),
      mode: currentMode,
    };

    setMessages((prev) => [...prev, userMessage]);
    setIsLoading(true);

    try {
      // Create a temporary "Thinking" message for better UX
      const tempId = (Date.now() + 1).toString();

      if (currentMode === ChatMode.CONSULTATION) {
          setMessages(prev => [...prev, {
              id: tempId,
              role: 'model',
              text: '',
              timestamp: new Date(),
              mode: currentMode,
              isThinking: true
          }]);
      }

      const response = await generateResponse({
        prompt: text,
        history: messages.map(m => ({
          role: m.role,
          parts: [{ text: m.text }]
        })),
        mode: currentMode,
        location: userLocation
      });

      if (currentMode === ChatMode.CONSULTATION) {
          // Replace thinking message
          setMessages(prev => prev.map(m => 
              m.id === tempId 
              ? { ...m, text: response.text, isThinking: false, groundingMetadata: response.groundingMetadata }
              : m
          ));
      } else {
          // Just add new message for other modes (faster response usually)
          const botMessage: Message = {
            id: Date.now().toString(),
            role: 'model',
            text: response.text,
            timestamp: new Date(),
            mode: currentMode,
            groundingMetadata: response.groundingMetadata
          };
          setMessages((prev) => [...prev, botMessage]);
      }

    } catch (error) {
      console.error(error);
      const errorMessage: Message = {
        id: Date.now().toString(),
        role: 'model',
        text: "I'm sorry, I'm having trouble connecting right now. Please try again later.",
        timestamp: new Date(),
        mode: currentMode,
      };
      setMessages((prev) => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">

      {!hasAcceptedDisclaimer && (
        <DisclaimerModal onAccept={() => setHasAcceptedDisclaimer(true)} />
      )}

      {/* Header */}
      <header className="bg-white px-6 py-4 border-b border-slate-200 flex items-center justify-between shadow-sm z-20">
        <div className="flex items-center gap-3">
          <div className="bg-blue-600 p-2 rounded-lg text-white">
            <Activity className="w-6 h-6" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">Dr. Gemini</h1>
            <div className="flex items-center gap-1.5">
               <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
               <p className="text-xs text-slate-500 font-medium">AI Assistant Online</p>
            </div>
          </div>
        </div>
      </header>

      {/* Mode Selector */}
      <ModeSelector 
        currentMode={currentMode} 
        onModeChange={setCurrentMode} 
        disabled={isLoading} 
      />

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto p-4 md:p-6 scrollbar-hide">
        <div className="max-w-4xl mx-auto min-h-full flex flex-col justify-end">
          {messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center text-center text-slate-400 my-auto py-20 opacity-0 animate-in fade-in slide-in-from-bottom-4 duration-700 fill-mode-forwards">
               <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center mb-6">
                 <Activity className="w-10 h-10 text-blue-300" />
               </div>
               <h3 className="text-lg font-semibold text-slate-600 mb-2">How can I help you today?</h3>
               <p className="max-w-md mx-auto mb-8">
                 Describe your symptoms, ask about a condition, or find nearby medical services.
               </p>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full max-w-lg">
                   <button onClick={() => handleSendMessage("I have a headache and fever.")} className="p-4 bg-white border border-slate-200 rounded-xl hover:border-blue-300 hover:shadow-md transition-all text-sm text-left">
                       🤒 "I have a headache and fever..."
                   </button>
                   <button onClick={() => {
                       setCurrentMode(ChatMode.FIND_CARE);
                       handleSendMessage("Where is the nearest pharmacy?");
                   }} className="p-4 bg-white border border-slate-200 rounded-xl hover:border-emerald-300 hover:shadow-md transition-all text-sm text-left">
