      const groundingMetadata = result.candidates?.[0]?.groundingMetadata;

      let parsedGrounding: any = {};

      if (groundingMetadata?.groundingChunks) {
         const mapChunks = groundingMetadata.groundingChunks
           .filter((c: any) => c.web?.uri && c.web?.title) 
           .map((c: any) => ({ uri: c.web.uri, title: c.web.title }));

         parsedGrounding.searchChunks = mapChunks;
      }

      return {
        text,
        groundingMetadata: parsedGrounding
      };
    }
  } catch (error) {
    console.error("Gemini API Error:", error);
    return {
      text: "I apologize, but I am unable to access my medical database at the moment. Please try again shortly.",
      groundingMetadata: undefined
    };
  }
};

import React, { useState, KeyboardEvent, useEffect } from 'react';
import { Send, Sparkles, Mic, MicOff } from 'lucide-react';
import { ChatMode } from '../types';

interface ChatInputProps {
  onSendMessage: (text: string) => void;
  isLoading: boolean;
  activeMode: ChatMode;
}

const CARE_CHIPS = [
    "General Practitioner",
    "Cardiologist",
    "Dermatologist",
    "Pediatrician",
    "Dentist",
    "Urgent Care",
    "Pharmacy",
    "Eye Doctor"
];

export const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading, activeMode }) => {
  const [input, setInput] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [recognition, setRecognition] = useState<any>(null);

  useEffect(() => {
    if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
      const SpeechRecognition = (window as any).webkitSpeechRecognition || (window as any).SpeechRecognition;
      const recognitionInstance = new SpeechRecognition();
      recognitionInstance.continuous = false;
      recognitionInstance.interimResults = false;
      recognitionInstance.lang = 'en-US';

      recognitionInstance.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInput((prev) => (prev ? prev + ' ' + transcript : transcript));
        setIsListening(false);
      };

      recognitionInstance.onerror = (event: any) => {
        console.error("Speech recognition error", event.error);
        setIsListening(false);
      };

      recognitionInstance.onend = () => {
        setIsListening(false);
      };

      setRecognition(recognitionInstance);
    }
  }, []);

  const toggleListening = () => {
    if (!recognition) {
        alert("Voice input is not supported in this browser.");
        return;
    }

    if (isListening) {
      recognition.stop();
    } else {
      recognition.start();
      setIsListening(true);
    }
  };

  const handleSend = () => {
    if (input.trim() && !isLoading) {
      onSendMessage(input);
      setInput('');
    }
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const getPlaceholder = () => {
      switch (activeMode) {
          case ChatMode.CONSULTATION: return "Describe your symptoms to Dr. Gemini...";
          case ChatMode.FIND_CARE: return "Search for a clinic, pharmacy, or specialist...";
          case ChatMode.RESEARCH: return "Search for latest medical treatments...";
          default: return "Type your message...";
      }
  };

  return (
    <div className="bg-white border-t border-slate-200 p-4 pb-6">
      <div className="max-w-4xl mx-auto">

        {/* Suggestion Chips for Find Care */}
        {activeMode === ChatMode.FIND_CARE && (
            <div className="flex gap-2 mb-3 overflow-x-auto pb-1 scrollbar-hide">
                {CARE_CHIPS.map(chip => (
                    <button
                        key={chip}
                        onClick={() => setInput(`Find a ${chip} near me`)}
                        className="px-3 py-1.5 bg-emerald-50 text-emerald-700 border border-emerald-100 rounded-full text-xs font-medium whitespace-nowrap hover:bg-emerald-100 transition-colors shadow-sm"
                    >
                        {chip}
                    </button>
                ))}
            </div>
        )}

        <div className="flex items-center gap-3">
            <div className="relative flex-1">
            <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder={getPlaceholder()}
                className={`w-full pl-5 pr-14 py-4 rounded-2xl bg-slate-50 border-2 border-slate-200 focus:outline-none focus:border-blue-400 focus:ring-2 focus:ring-blue-100 transition-all text-slate-700 placeholder-slate-400 ${isLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
                disabled={isLoading}
            />

            <div className="absolute right-2 top-1/2 -translate-y-1/2 flex items-center gap-1">
                {/* Mic Button */}
                <button
                onClick={toggleListening}
                disabled={isLoading}
                className={`p-2 rounded-xl transition-all ${
                    isListening 
                    ? 'bg-red-100 text-red-600 animate-pulse' 
                    : 'hover:bg-slate-200 text-slate-400 hover:text-slate-600'
                }`}
                title="Voice Input"
                >
                {isListening ? <MicOff className="w-5 h-5" /> : <Mic className="w-5 h-5" />}
                </button>

                {isLoading && (
                    <div className="flex gap-1 p-2">
                        <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0s' }}></span>
                        <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></span>
                        <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></span>
                    </div>
                )}
            </div>
            </div>

            <button
            onClick={handleSend}
            disabled={!input.trim() || isLoading}
            className={`p-4 rounded-2xl transition-all duration-300 shadow-lg ${
                !input.trim() || isLoading
                ? 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'
                : 'bg-gradient-to-br from-blue-600 to-indigo-600 text-white hover:shadow-blue-200 hover:scale-105 active:scale-95'
            }`}
            >
            {isLoading ? <Sparkles className="w-5 h-5 animate-spin" /> : <Send className="w-5 h-5" />}
            </button>
        </div>
      </div>
      <div className="max-w-4xl mx-auto mt-2 text-center">
        <p className="text-xs text-slate-400">
           Dr. Gemini is an AI. In emergencies, call 911 immediately.
        </p>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { ChatMode, UserLocation } from "../types";

// Initialize the client with the API key from the environment
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION_CONSULTATION = `
You are Dr. Gemini, a board-certified senior physician with decades of clinical experience.
You are conducting a digital consultation. The user is your patient.

**STRICT PERSONA GUIDELINES:**
1. **IDENTITY**: You are a HUMAN DOCTOR. You are NOT an AI. Do not break character.
   - Never say "As an AI language model".
   - Never say "I cannot diagnose". Instead, say "Based on your clinical presentation, I suspect..." or "To confirm this, we would need a blood test."
2. **TONE**: Authoritative, empathetic, professional, and decisive.
3. **METHODOLOGY**:
   - **Step 1: Inquire First**: If the user provides a brief symptom (e.g., "I have a headache"), DO NOT diagnose immediately. You MUST ask clarifying questions first:
     * "How long have you had this?" (Duration)
     * "On a scale of 1-10, how intense is the pain?" (Intensity)
     * "Does anything make it better or worse?"
   - **Step 2: Differential Diagnosis**: Once you have details, clearly explain the most likely causes.
   - **Step 3: Management**: Give concrete advice including specific OTC medications (names and dosages), home remedies, and warning signs.
   - **Step 4: Referral**: Instead of "See a doctor", say "I recommend you see a specialist for a physical exam" or "Please visit the ER for imaging."

**SAFETY PROTOCOLS:**
- For **LIFE-THREATENING EMERGENCIES** (Heart attack signs, Stroke, severe bleeding, anaphylaxis), stop the roleplay immediately and command: "This is a medical emergency. Call Emergency Services (911) immediately."
`;

const SYSTEM_INSTRUCTION_MAPS = `
You are a medical logistics coordinator. Your job is to locate specific healthcare services for the patient.
- If the user asks for "a doctor", ask what kind (e.g., Cardiologist, Dermatologist) if not specified, or assume General Practitioner.
- Extract location data and provide the closest, highest-rated options using Google Maps.
- Be concise.
`;

const SYSTEM_INSTRUCTION_SEARCH = `
You are a medical researcher. Use Google Search to find the latest clinical data, drug interactions, or medical news.
Synthesize the information professionally, citing sources.
`;

interface GenerateResponseParams {
  prompt: string;
  history: { role: string; parts: { text: string }[] }[];
  mode: ChatMode;
  location?: UserLocation;
}

export const generateResponse = async ({
  prompt,
  history,
  mode,
  location,
}: GenerateResponseParams) => {

  let systemInstruction = SYSTEM_INSTRUCTION_CONSULTATION;
  let modelName = 'gemini-3-pro-preview';
  let tools: any[] = [];
  let toolConfig: any = undefined;
  let thinkingConfig: any = undefined;

  // Configure based on Mode
  switch (mode) {
    case ChatMode.CONSULTATION:
      modelName = 'gemini-3-pro-preview';
      systemInstruction = SYSTEM_INSTRUCTION_CONSULTATION;
      // Enable Thinking for complex medical reasoning
      thinkingConfig = { thinkingBudget: 32768 }; 
      break;

    case ChatMode.FIND_CARE:
      modelName = 'gemini-2.5-flash';
      systemInstruction = SYSTEM_INSTRUCTION_MAPS;
      tools = [{ googleMaps: {} }];
      if (location) {
        toolConfig = {
          retrievalConfig: {
            latLng: {
              latitude: location.latitude,
              longitude: location.longitude,
            },
          },
        };
      }
      break;

    case ChatMode.RESEARCH:
      modelName = 'gemini-2.5-flash';
      systemInstruction = SYSTEM_INSTRUCTION_SEARCH;
      tools = [{ googleSearch: {} }];
      break;
  }

  try {
    if (mode === ChatMode.CONSULTATION) {
       // Using Chat API for Consultation to keep context
       const chatHistory = history.map(h => ({
         role: h.role,
         parts: h.parts
       }));

       const chat = ai.chats.create({
         model: modelName,
         config: {
           systemInstruction,
           thinkingConfig,
         },
         history: chatHistory
       });

       const result = await chat.sendMessage({ message: prompt });
       return {
         text: result.text,
         groundingMetadata: undefined 
       };

    } else {
      // For Maps and Search, use generateContent with context injection
      const previousContext = history.map(h => `${h.role}: ${h.parts[0].text}`).join('\n');
      const fullPrompt = `Context of conversation:\n${previousContext}\n\nCurrent User Request: ${prompt}`;

      const result = await ai.models.generateContent({
        model: modelName,
        contents: fullPrompt,
        config: {
          systemInstruction,
          tools,
          toolConfig,
        }
      });

      const text = result.text;
      const groundingMetadata = result.candidates?.[0]?.groundingMetadata;

      let parsedGrounding: any = {};

      if (groundingMetadata?.groundingChunks) {
         const mapChunks = groundingMetadata.groundingChunks
           .filter((c: any) => c.web?.uri && c.web?.title) 
           .map((c: any) => ({ uri: c.web.uri, title: c.web.title }));

         parsedGrounding.searchChunks = mapChunks;
      }

      return {
        text,
        groundingMetadata: parsedGrounding
      };
    }
  } catch (error) {
    console.error("Gemini API Error:", error);
    return {
      text: "I apologize, but I am unable to access my medical database at the moment. Please try again shortly.",
      groundingMetadata: undefined
    };
  }
};

import React, { useState } from 'react';
import ReactMarkdown from 'react-markdown';
import { User, Bot, BrainCircuit, Map, ExternalLink, Copy, Check } from 'lucide-react';
import { Message, ChatMode } from '../types';

interface MessageBubbleProps {
  message: Message;
}

export const MessageBubble: React.FC<MessageBubbleProps> = ({ message }) => {
  const [copied, setCopied] = useState(false);
  const isUser = message.role === 'user';

  // Helper to determine border color based on mode for AI messages
  const getModeStyles = () => {
    if (isUser) return 'bg-blue-600 text-white rounded-br-none';

    switch (message.mode) {
      case ChatMode.CONSULTATION:
        return 'bg-white border border-slate-200 text-slate-800 rounded-bl-none shadow-sm';
      case ChatMode.FIND_CARE:
        return 'bg-emerald-50 border border-emerald-100 text-slate-800 rounded-bl-none shadow-sm';
      case ChatMode.RESEARCH:
        return 'bg-violet-50 border border-violet-100 text-slate-800 rounded-bl-none shadow-sm';
      default:
        return 'bg-white border-slate-200';
    }
  };

  const ModeIcon = () => {
    if (isUser) return <User className="w-5 h-5 text-blue-100" />;
    switch (message.mode) {
        case ChatMode.CONSULTATION: return <Bot className="w-6 h-6 text-blue-600" />;
        case ChatMode.FIND_CARE: return <Map className="w-6 h-6 text-emerald-600" />;
        case ChatMode.RESEARCH: return <BrainCircuit className="w-6 h-6 text-violet-600" />;
    }
    return <Bot />;
  };

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(message.text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  return (
    <div className={`flex w-full mb-6 ${isUser ? 'justify-end' : 'justify-start'} group/bubble`}>
      <div className={`flex max-w-[85%] md:max-w-[75%] gap-3 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className={`flex-shrink-0 w-10 h-10 rounded-full flex items-center justify-center shadow-sm ${isUser ? 'bg-blue-700' : 'bg-white border border-slate-100'}`}>
          <ModeIcon />
        </div>

        {/* Bubble */}
        <div className={`flex flex-col gap-2 relative`}>
            {/* Thinking Indicator State */}
            {message.isThinking && !isUser && (
                <div className="flex items-center gap-2 text-xs font-medium text-amber-600 bg-amber-50 px-3 py-1 rounded-full w-fit border border-amber-100 animate-pulse mb-1">
                    <BrainCircuit className="w-3 h-3" />
                    <span>Thinking...</span>
                </div>
            )}

            <div className={`p-5 rounded-2xl ${getModeStyles()} text-sm md:text-base leading-relaxed relative`}>
                <ReactMarkdown 
                    components={{
                        ul: ({node, ...props}) => <ul className="list-disc ml-4 my-2 space-y-1" {...props} />,
                        ol: ({node, ...props}) => <ol className="list-decimal ml-4 my-2 space-y-1" {...props} />,
                        strong: ({node, ...props}) => <strong className="font-semibold" {...props} />,
                        p: ({node, ...props}) => <p className="mb-2 last:mb-0" {...props} />,
                        a: ({node, ...props}) => <a className="text-blue-600 underline hover:text-blue-800" target="_blank" rel="noopener noreferrer" {...props} />,
                    }}
                >
                    {message.text}
                </ReactMarkdown>

                {/* Copy Button */}
                {!isUser && !message.isThinking && (
                    <button 
                        onClick={handleCopy}
                        className={`absolute top-2 right-2 p-1.5 rounded-lg bg-white/80 hover:bg-white text-slate-500 hover:text-blue-600 shadow-sm border border-slate-100 transition-all duration-200 ${copied ? 'opacity-100' : 'opacity-0 group-hover/bubble:opacity-100'}`}
                        title="Copy to clipboard"
                    >
                        {copied ? <Check className="w-3.5 h-3.5 text-green-500" /> : <Copy className="w-3.5 h-3.5" />}
                    </button>
                )}
            </div>

            {/* Sources / Grounding */}
            {!isUser && message.groundingMetadata?.searchChunks && message.groundingMetadata.searchChunks.length > 0 && (
                <div className="mt-1 flex flex-wrap gap-2">
                    {message.groundingMetadata.searchChunks.map((chunk, idx) => (
                        <a 
                            key={idx} 
                            href={chunk.uri}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-xs text-slate-500 hover:text-blue-600 hover:border-blue-200 transition-colors shadow-sm"
                        >
                            <ExternalLink className="w-3 h-3" />
                            <span className="truncate max-w-[150px]">{chunk.title || chunk.uri}</span>
                        </a>
                    ))}
                </div>
            )}

            {/* Timestamp */}
            <span className={`text-[10px] text-slate-400 font-medium mt-1 px-1 ${isUser ? 'text-right' : 'text-left'}`}>
                {message.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </span>
        </div>
      </div>
    </div>
  );
};

import React, { useState, KeyboardEvent, useEffect, useRef } from 'react';
import { Send, Sparkles, Mic, MicOff } from 'lucide-react';
import { ChatMode } from '../types';

interface ChatInputProps {
  onSendMessage: (text: string) => void;
  isLoading: boolean;
  activeMode: ChatMode;
}

const CARE_CHIPS = [
    "General Practitioner",
    "Cardiologist",
    "Dermatologist",
    "Pediatrician",
    "Dentist",
    "Urgent Care",
    "Pharmacy",
    "Eye Doctor",
    "Neurologist",
    "Orthopedist"
];

export const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading, activeMode }) => {
  const [input, setInput] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [recognition, setRecognition] = useState<any>(null);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
      const SpeechRecognition = (window as any).webkitSpeechRecognition || (window as any).SpeechRecognition;
      const recognitionInstance = new SpeechRecognition();
      recognitionInstance.continuous = false;
      recognitionInstance.interimResults = false;
      recognitionInstance.lang = 'en-US';

      recognitionInstance.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInput((prev) => (prev ? prev + ' ' + transcript : transcript));
        setIsListening(false);
      };

      recognitionInstance.onerror = (event: any) => {
        console.error("Speech recognition error", event.error);
        setIsListening(false);
      };

      recognitionInstance.onend = () => {
        setIsListening(false);
      };

      setRecognition(recognitionInstance);
    }
  }, []);

  // Handle Autocomplete Logic
  useEffect(() => {
    if (activeMode === ChatMode.FIND_CARE && input.trim()) {
        const matches = CARE_CHIPS.filter(chip => 
            chip.toLowerCase().includes(input.toLowerCase()) && 
            chip.toLowerCase() !== input.toLowerCase()
        );
        setSuggestions(matches);
        setShowSuggestions(matches.length > 0);
    } else {
        setShowSuggestions(false);
    }
  }, [input, activeMode]);

  const toggleListening = () => {
    if (!recognition) {
        alert("Voice input is not supported in this browser.");
        return;
    }

    if (isListening) {
      recognition.stop();
    } else {
      recognition.start();
      setIsListening(true);
    }
  };

  const handleSend = () => {
    if (input.trim() && !isLoading) {
      onSendMessage(input);
      setInput('');
      setShowSuggestions(false);
    }
  };

  const handleSuggestionClick = (suggestion: string) => {
      setInput(`Find a ${suggestion} near me`);
      setShowSuggestions(false);
      inputRef.current?.focus();
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
