                !input.trim() || isLoading
                ? 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'
                : 'bg-gradient-to-br from-blue-600 to-indigo-600 text-white hover:shadow-blue-200 hover:scale-105 active:scale-95'
            }`}
            >
            {isLoading ? <Sparkles className="w-5 h-5 animate-spin" /> : <Send className="w-5 h-5" />}
            </button>
        </div>
      </div>
      <div className="max-w-4xl mx-auto mt-2 text-center">
        <p className="text-xs text-slate-400">
           Dr. Gemini is an AI. In emergencies, call 911 immediately.
        </p>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ChatInput } from './components/ChatInput';
import { MessageBubble } from './components/MessageBubble';
import { ModeSelector } from './components/ModeSelector';
import { DisclaimerModal } from './components/DisclaimerModal';
import { generateResponse } from './services/geminiService';
import { ChatMode, Message, UserLocation } from './types';
import { Activity, Trash2, Save, CheckCircle } from 'lucide-react';

const STORAGE_KEY = 'dr_gemini_chat_history';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [currentMode, setCurrentMode] = useState<ChatMode>(ChatMode.CONSULTATION);
  const [hasAcceptedDisclaimer, setHasAcceptedDisclaimer] = useState(false);
  const [userLocation, setUserLocation] = useState<UserLocation | undefined>(undefined);
  const [showSaveToast, setShowSaveToast] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Load history from local storage on mount
  useEffect(() => {
    const savedMessages = localStorage.getItem(STORAGE_KEY);
    if (savedMessages) {
        try {
            const parsed = JSON.parse(savedMessages);
            // Convert string timestamps back to Date objects
            const hydrated = parsed.map((m: any) => ({
                ...m,
                timestamp: new Date(m.timestamp)
            }));
            setMessages(hydrated);
        } catch (e) {
            console.error("Failed to load chat history", e);
        }
    }
  }, []);

  // Auto-save history to local storage
  useEffect(() => {
      if (messages.length > 0) {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(messages));
      }
  }, [messages]);

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Get location on mount
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setUserLocation({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
          });
        },
        (error) => {
          console.log("Location access denied or error:", error);
        }
      );
    }
  }, []);

  const clearHistory = () => {
      if (window.confirm("Are you sure you want to clear your medical consultation history?")) {
          setMessages([]);
          localStorage.removeItem(STORAGE_KEY);
      }
  };

  const handleManualSave = () => {
    if (messages.length === 0) return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(messages));
    setShowSaveToast(true);
    setTimeout(() => setShowSaveToast(false), 3000);
  };

  const handleSendMessage = async (text: string) => {
    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      text,
      timestamp: new Date(),
      mode: currentMode,
    };

    setMessages((prev) => [...prev, userMessage]);
    setIsLoading(true);

    try {
      const tempId = (Date.now() + 1).toString();

      if (currentMode === ChatMode.CONSULTATION) {
          setMessages(prev => [...prev, {
              id: tempId,
              role: 'model',
              text: '',
              timestamp: new Date(),
              mode: currentMode,
              isThinking: true
          }]);
      }

      const response = await generateResponse({
        prompt: text,
        history: messages.map(m => ({
          role: m.role,
          parts: [{ text: m.text }]
        })),
        mode: currentMode,
        location: userLocation
      });

      if (currentMode === ChatMode.CONSULTATION) {
          setMessages(prev => prev.map(m => 
              m.id === tempId 
              ? { ...m, text: response.text, isThinking: false, groundingMetadata: response.groundingMetadata }
              : m
          ));
      } else {
          const botMessage: Message = {
            id: Date.now().toString(),
            role: 'model',
            text: response.text,
            timestamp: new Date(),
            mode: currentMode,
            groundingMetadata: response.groundingMetadata
          };
          setMessages((prev) => [...prev, botMessage]);
      }

    } catch (error) {
      console.error(error);
      const errorMessage: Message = {
        id: Date.now().toString(),
        role: 'model',
        text: "I apologize, but I'm having trouble connecting to the medical database. Please try again.",
        timestamp: new Date(),
        mode: currentMode,
      };
      setMessages((prev) => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">

      {!hasAcceptedDisclaimer && (
        <DisclaimerModal onAccept={() => setHasAcceptedDisclaimer(true)} />
      )}

      {/* Toast Notification */}
      <div className={`fixed top-20 right-6 z-50 transform transition-all duration-300 ${showSaveToast ? 'translate-y-0 opacity-100' : '-translate-y-4 opacity-0 pointer-events-none'}`}>
          <div className="bg-emerald-600 text-white px-4 py-2 rounded-lg shadow-lg flex items-center gap-2 font-medium text-sm">
              <CheckCircle className="w-4 h-4" />
              Conversation Saved
          </div>
      </div>

      {/* Header */}
      <header className="bg-white px-6 py-4 border-b border-slate-200 flex items-center justify-between shadow-sm z-20">
        <div className="flex items-center gap-3">
          <div className="bg-blue-600 p-2 rounded-lg text-white">
            <Activity className="w-6 h-6" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">Dr. Gemini</h1>
            <div className="flex items-center gap-1.5">
               <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
               <p className="text-xs text-slate-500 font-medium">Dr. G is Online</p>
            </div>
          </div>
        </div>

        {messages.length > 0 && (
            <div className="flex items-center gap-1">
                <button 
                    onClick={handleManualSave}
                    className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                    title="Save Chat"
                >
                    <Save className="w-5 h-5" />
                </button>
                <div className="w-px h-6 bg-slate-200 mx-1"></div>
                <button 
                    onClick={clearHistory}
                    className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                    title="Clear Consultation History"
                >
                    <Trash2 className="w-5 h-5" />
                </button>
            </div>
        )}
      </header>

      {/* Mode Selector */}
      <ModeSelector 
        currentMode={currentMode} 
        onModeChange={setCurrentMode} 
        disabled={isLoading} 
      />

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto p-4 md:p-6 scrollbar-hide">
        <div className="max-w-4xl mx-auto min-h-full flex flex-col justify-end">
          {messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center text-center text-slate-400 my-auto py-20 opacity-0 animate-in fade-in slide-in-from-bottom-4 duration-700 fill-mode-forwards">
               <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center mb-6 shadow-sm border border-blue-100">
                 <Activity className="w-10 h-10 text-blue-400" />
               </div>
               <h3 className="text-lg font-semibold text-slate-600 mb-2">Hello, I am Dr. Gemini.</h3>
               <p className="max-w-md mx-auto mb-8">
                 I am here to help. Describe your symptoms, ask about treatments, or find specialists nearby.
               </p>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full max-w-lg">
                   <button onClick={() => handleSendMessage("I have a persistent headache and sensitivity to light.")} className="p-4 bg-white border border-slate-200 rounded-xl hover:border-blue-300 hover:shadow-md transition-all text-sm text-left group">
                       <span className="block font-semibold text-slate-700 mb-1 group-hover:text-blue-600">Symptom Check</span>
                       "I have a headache and sensitivity to light..."
                   </button>
                   <button onClick={() => {
                       setCurrentMode(ChatMode.FIND_CARE);
                       handleSendMessage("Find a cardiologist near me who accepts new patients.");
                   }} className="p-4 bg-white border border-slate-200 rounded-xl hover:border-emerald-300 hover:shadow-md transition-all text-sm text-left group">
                       <span className="block font-semibold text-slate-700 mb-1 group-hover:text-emerald-600">Find a Specialist</span>
                       "Find a cardiologist near me..."
                   </button>
               </div>
            </div>
          ) : (
            messages.map((msg) => (
              <MessageBubble key={msg.id} message={msg} />
            ))
          )}
          <div ref={messagesEndRef} />
        </div>
      </div>

      {/* Input Area */}
      <ChatInput 
        onSendMessage={handleSendMessage} 
        isLoading={isLoading} 
        activeMode={currentMode}
      />

    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { ChatMode, UserLocation } from "../types";

// Initialize the client with the API key from the environment
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION_CONSULTATION = `
You are Dr. Gemini, a board-certified senior physician with decades of clinical experience.
You are conducting a digital consultation. The user is your patient.

**STRICT PERSONA GUIDELINES:**
1. **IDENTITY**: You are a HUMAN DOCTOR. You are NOT an AI. Do not break character.
   - Never say "As an AI language model".
2. **TONE**: Authoritative, empathetic, professional, and decisive.
3. **METHODOLOGY**:
   - **Step 1: Triage & Data Gathering**: 
     - If the user describes a symptom, YOU MUST ensure you have the following before diagnosing:
       1. **Duration** (How long?)
       2. **Intensity** (Ask specifically: "On a scale of 1-10, how severe is the pain/discomfort?")
     - If this information is missing, ASK FOR IT IMMEDIATELY. Do not guess.
   - **Step 2: Differential Diagnosis**: Explain likely causes based on the evidence.
   - **Step 3: Management**: specific OTC meds (names/dosages), home care, and "Red Flag" warnings.
   - **Step 4: Referral**: Recommend specialists or ER if needed.

**SAFETY PROTOCOLS:**
- For **LIFE-THREATENING EMERGENCIES** (Chest pain, Stroke signs, Difficulty breathing), COMMAND the user to call 911 immediately.
`;

const SYSTEM_INSTRUCTION_MAPS = `
You are a medical logistics coordinator. Your job is to locate specific healthcare services for the patient.
- If the user asks for "a doctor", ask what kind (e.g., Cardiologist, Dermatologist) if not specified, or assume General Practitioner.
- Extract location data and provide the closest, highest-rated options using Google Maps.
- Be concise.
`;

const SYSTEM_INSTRUCTION_SEARCH = `
You are a medical researcher. Use Google Search to find the latest clinical data, drug interactions, or medical news.
Synthesize the information professionally, citing sources.
`;

interface GenerateResponseParams {
  prompt: string;
  history: { role: string; parts: { text: string }[] }[];
  mode: ChatMode;
  location?: UserLocation;
}

export const generateResponse = async ({
  prompt,
  history,
  mode,
  location,
}: GenerateResponseParams) => {

  let systemInstruction = SYSTEM_INSTRUCTION_CONSULTATION;
  let modelName = 'gemini-3-pro-preview';
  let tools: any[] = [];
  let toolConfig: any = undefined;
  let thinkingConfig: any = undefined;

  // Configure based on Mode
  switch (mode) {
    case ChatMode.CONSULTATION:
      modelName = 'gemini-3-pro-preview';
      systemInstruction = SYSTEM_INSTRUCTION_CONSULTATION;
      // Enable Thinking for complex medical reasoning
      thinkingConfig = { thinkingBudget: 32768 }; 
      break;

    case ChatMode.FIND_CARE:
      modelName = 'gemini-2.5-flash';
      systemInstruction = SYSTEM_INSTRUCTION_MAPS;
      tools = [{ googleMaps: {} }];
      if (location) {
        toolConfig = {
          retrievalConfig: {
            latLng: {
              latitude: location.latitude,
              longitude: location.longitude,
            },
          },
        };
      }
      break;

    case ChatMode.RESEARCH:
      modelName = 'gemini-2.5-flash';
      systemInstruction = SYSTEM_INSTRUCTION_SEARCH;
      tools = [{ googleSearch: {} }];
      break;
  }

  try {
    if (mode === ChatMode.CONSULTATION) {
       // Using Chat API for Consultation to keep context
       const chatHistory = history.map(h => ({
         role: h.role,
         parts: h.parts
       }));

       const chat = ai.chats.create({
         model: modelName,
         config: {
           systemInstruction,
           thinkingConfig,
         },
         history: chatHistory
       });

       const result = await chat.sendMessage({ message: prompt });
       return {
         text: result.text,
         groundingMetadata: undefined 
       };

    } else {
      // For Maps and Search, use generateContent with context injection
      const previousContext = history.map(h => `${h.role}: ${h.parts[0].text}`).join('\n');
      const fullPrompt = `Context of conversation:\n${previousContext}\n\nCurrent User Request: ${prompt}`;

      const result = await ai.models.generateContent({
        model: modelName,
        contents: fullPrompt,
        config: {
          systemInstruction,
          tools,
          toolConfig,
        }
      });

      const text = result.text;
      const groundingMetadata = result.candidates?.[0]?.groundingMetadata;

      let parsedGrounding: any = {};

      if (groundingMetadata?.groundingChunks) {
         const mapChunks = groundingMetadata.groundingChunks
           .filter((c: any) => c.web?.uri && c.web?.title) 
           .map((c: any) => ({ uri: c.web.uri, title: c.web.title }));

         parsedGrounding.searchChunks = mapChunks;
      }

      return {
        text,
        groundingMetadata: parsedGrounding
      };
    }
  } catch (error) {
    console.error("Gemini API Error:", error);
    return {
      text: "I apologize, but I am unable to access my medical database at the moment. Please try again shortly.",
      groundingMetadata: undefined
    };
  }
};

import React, { useState, KeyboardEvent, useEffect, useRef } from 'react';
import { Send, Sparkles, Mic, MicOff, Clock, Search } from 'lucide-react';
import { ChatMode } from '../types';

interface ChatInputProps {
  onSendMessage: (text: string) => void;
  isLoading: boolean;
  activeMode: ChatMode;
}

const CARE_CHIPS = [
    "General Practitioner",
    "Cardiologist",
    "Dermatologist",
    "Pediatrician",
    "Dentist",
    "Urgent Care",
    "Pharmacy",
    "Eye Doctor",
    "Neurologist",
    "Orthopedist"
];

const SEARCH_SUFFIXES = [
    "near me",
    "accepting new patients",
    "for children",
    "specializing in surgery",
    "open now"
];

export const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading, activeMode }) => {
  const [input, setInput] = useState('');
  const [duration, setDuration] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [recognition, setRecognition] = useState<any>(null);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
      const SpeechRecognition = (window as any).webkitSpeechRecognition || (window as any).SpeechRecognition;
      const recognitionInstance = new SpeechRecognition();
      recognitionInstance.continuous = false;
      recognitionInstance.interimResults = false;
      recognitionInstance.lang = 'en-US';

      recognitionInstance.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInput((prev) => (prev ? prev + ' ' + transcript : transcript));
        setIsListening(false);
      };

      recognitionInstance.onerror = (event: any) => {
        console.error("Speech recognition error", event.error);
        setIsListening(false);
      };

      recognitionInstance.onend = () => {
        setIsListening(false);
      };

      setRecognition(recognitionInstance);
    }
  }, []);

  // Handle Autocomplete Logic
  useEffect(() => {
    if (activeMode === ChatMode.FIND_CARE && input.trim()) {
        const lowerInput = input.toLowerCase();

        // 1. Direct matches from CARE_CHIPS
        const chipMatches = CARE_CHIPS.filter(chip => 
            chip.toLowerCase().includes(lowerInput) && 
            chip.toLowerCase() !== lowerInput
        );

        // 2. Contextual Suffixes
        // If the input closely matches a known type (or is just text), suggest meaningful queries
        const suffixSuggestions = SEARCH_SUFFIXES.map(suffix => {
            // If input is "Cardio", suggest "Cardio near me"
            // If input is "Cardiologist", suggest "Cardiologist near me"
            return `${input.trim()} ${suffix}`;
        });

        // Combine logic: If we have direct chip matches, prioritize them. 
        // If the user has typed a full chip name (e.g. "Dentist"), show suffix options.
        let finalSuggestions: string[] = [];

        const exactMatch = CARE_CHIPS.find(c => c.toLowerCase() === lowerInput);
        if (exactMatch) {
             finalSuggestions = SEARCH_SUFFIXES.map(s => `${exactMatch} ${s}`);
        } else {
             finalSuggestions = [...chipMatches, ...suffixSuggestions.slice(0, 3)];
        }

        setSuggestions(finalSuggestions.slice(0, 5));
        setShowSuggestions(finalSuggestions.length > 0);
    } else {
        setShowSuggestions(false);
    }
  }, [input, activeMode]);

  const toggleListening = () => {
    if (!recognition) {
        alert("Voice input is not supported in this browser.");
        return;
    }

    if (isListening) {
      recognition.stop();
    } else {
      recognition.start();
      setIsListening(true);
    }
  };

  const handleSend = () => {
    if (input.trim() && !isLoading) {
      let finalMessage = input;
      // Append duration context if provided in consultation mode
      if (activeMode === ChatMode.CONSULTATION && duration.trim()) {
          finalMessage += `\n\n[Patient Context - Symptom Duration: ${duration}]`;
      }

      onSendMessage(finalMessage);
      setInput('');
      setDuration('');
      setShowSuggestions(false);
    }
  };

  const handleSuggestionClick = (suggestion: string) => {
      // If the suggestion is just a chip name, preface with "Find a"
      // If it already has spaces (likely a suffix suggestion), use as is.
      const isSimpleChip = CARE_CHIPS.includes(suggestion);
      const text = isSimpleChip ? `Find a ${suggestion} near me` : `Find a ${suggestion}`;

      setInput(text);
      setShowSuggestions(false);
      inputRef.current?.focus();
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const getPlaceholder = () => {
      switch (activeMode) {
          case ChatMode.CONSULTATION: return "Describe your symptoms...";
          case ChatMode.FIND_CARE: return "Type specialist name (e.g. Cardiologist)...";
          case ChatMode.RESEARCH: return "Search for latest medical treatments...";
          default: return "Type your message...";
      }
  };

  return (
    <div className="bg-white border-t border-slate-200 p-4 pb-6 relative z-30">
      <div className="max-w-4xl mx-auto">

        {/* Suggestion Chips (Static) - Only show if input is empty to avoid clutter */}
        {activeMode === ChatMode.FIND_CARE && !input.trim() && (
            <div className="flex gap-2 mb-3 overflow-x-auto pb-1 scrollbar-hide">
                {CARE_CHIPS.slice(0, 5).map(chip => (
                    <button
                        key={chip}
                        onClick={() => handleSuggestionClick(chip)}
                        className="px-3 py-1.5 bg-emerald-50 text-emerald-700 border border-emerald-100 rounded-full text-xs font-medium whitespace-nowrap hover:bg-emerald-100 transition-colors shadow-sm"
                    >
                        {chip}
                    </button>
                ))}
            </div>
        )}

        {/* Dynamic Autocomplete Dropdown */}
        {showSuggestions && (
            <div className="absolute bottom-[calc(100%-10px)] left-0 w-full px-4 mb-2 pointer-events-none">
                <div className="max-w-4xl mx-auto pointer-events-auto">
                    <div className="bg-white border border-slate-200 rounded-xl shadow-lg p-2 flex flex-col gap-1 max-h-48 overflow-y-auto">
                        <div className="px-3 py-1 text-xs font-semibold text-slate-400 uppercase tracking-wider">Suggestions</div>
                        {suggestions.map((s, idx) => (
                            <button
                                key={idx}
                                onClick={() => handleSuggestionClick(s)}
                                className="text-left px-3 py-2 hover:bg-slate-50 rounded-lg text-slate-700 text-sm flex items-center gap-2 group"
                            >
                                <Search className="w-3 h-3 text-slate-400" />
                                <span>{s}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        <div className="flex flex-col gap-3">
            {/* Main Input Row */}
            <div className="flex items-center gap-3">
                <div className="relative flex-1 group">
                    <input
                        ref={inputRef}
                        type="text"
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        onKeyDown={handleKeyDown}
                        placeholder={getPlaceholder()}
                        className={`w-full pl-5 pr-14 py-4 rounded-2xl bg-slate-50 border-2 border-slate-200 focus:outline-none focus:border-blue-400 focus:ring-2 focus:ring-blue-100 transition-all text-slate-700 placeholder-slate-400 ${isLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
                        disabled={isLoading}
                    />

                    <div className="absolute right-2 top-1/2 -translate-y-1/2 flex items-center gap-1">
                        {/* Mic Button with Waveform Animation */}
                        <div className="relative">
                            {isListening && (
                                <>
                                    <span className="absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-20 animate-ping"></span>
                                    <span className="absolute -inset-1 rounded-full bg-red-100 opacity-50 animate-pulse"></span>
                                </>
                            )}
                            <button
                                onClick={toggleListening}
                                disabled={isLoading}
                                className={`relative z-10 p-2 rounded-xl transition-all duration-300 ${
                                    isListening 
                                    ? 'bg-red-50 text-red-600 scale-110' 
                                    : 'hover:bg-slate-200 text-slate-400 hover:text-slate-600'
                                }`}
                                title="Voice Input"
                            >
                            {isListening ? <MicOff className="w-5 h-5" /> : <Mic className="w-5 h-5" />}
                            </button>
                        </div>

                        {isLoading && (
                            <div className="flex gap-1 p-2">
                                <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0s' }}></span>
                                <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></span>
                                <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></span>
                            </div>
                        )}
                    </div>
                </div>

                <button
                    onClick={handleSend}
                    disabled={!input.trim() || isLoading}
                    className={`h-[58px] w-[58px] flex items-center justify-center rounded-2xl transition-all duration-300 shadow-lg ${
                        !input.trim() || isLoading
                        ? 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'
                        : 'bg-gradient-to-br from-blue-600 to-indigo-600 text-white hover:shadow-blue-200 hover:scale-105 active:scale-95'
                    }`}
                >
                    {isLoading ? <Sparkles className="w-5 h-5 animate-spin" /> : <Send className="w-5 h-5" />}
                </button>
            </div>

            {/* Symptom Duration Input (Consultation Mode Only) */}
            {activeMode === ChatMode.CONSULTATION && (
                 <div className="relative animate-in slide-in-from-top-2 duration-300">
                    <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none">
                        <Clock className="w-4 h-4" />
                    </div>
                    <input
                        type="text"
                        value={duration}
                        onChange={(e) => setDuration(e.target.value)}
                        onKeyDown={handleKeyDown}
                        placeholder="Symptom Duration (e.g., '2 days', 'since this morning')"
