        <p className="text-xs text-slate-400">
           Dr. Gemini is an AI. In emergencies, call 911 immediately.
        </p>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import ReactMarkdown from 'react-markdown';
import { User, Bot, BrainCircuit, Map, ExternalLink, Copy, Check, Link2 } from 'lucide-react';
import { Message, ChatMode } from '../types';

interface MessageBubbleProps {
  message: Message;
}

export const MessageBubble: React.FC<MessageBubbleProps> = ({ message }) => {
  const [copied, setCopied] = useState(false);
  const isUser = message.role === 'user';

  // Helper to determine border color based on mode for AI messages
  const getModeStyles = () => {
    if (isUser) return 'bg-blue-600 text-white rounded-br-none';

    switch (message.mode) {
      case ChatMode.CONSULTATION:
        return 'bg-white border border-slate-200 text-slate-800 rounded-bl-none shadow-sm';
      case ChatMode.FIND_CARE:
        return 'bg-emerald-50 border border-emerald-100 text-slate-800 rounded-bl-none shadow-sm';
      case ChatMode.RESEARCH:
        return 'bg-violet-50 border border-violet-100 text-slate-800 rounded-bl-none shadow-sm';
      default:
        return 'bg-white border-slate-200';
    }
  };

  const ModeIcon = () => {
    if (isUser) return <User className="w-5 h-5 text-blue-100" />;
    switch (message.mode) {
        case ChatMode.CONSULTATION: return <Bot className="w-6 h-6 text-blue-600" />;
        case ChatMode.FIND_CARE: return <Map className="w-6 h-6 text-emerald-600" />;
        case ChatMode.RESEARCH: return <BrainCircuit className="w-6 h-6 text-violet-600" />;
    }
    return <Bot />;
  };

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(message.text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  return (
    <div className={`flex w-full mb-6 ${isUser ? 'justify-end' : 'justify-start'} group/bubble`}>
      <div className={`flex max-w-[85%] md:max-w-[75%] gap-3 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className={`flex-shrink-0 w-10 h-10 rounded-full flex items-center justify-center shadow-sm ${isUser ? 'bg-blue-700' : 'bg-white border border-slate-100'}`}>
          <ModeIcon />
        </div>

        {/* Bubble */}
        <div className={`flex flex-col gap-2 relative min-w-[200px]`}>
            {/* Thinking Indicator State */}
            {message.isThinking && !isUser && (
                <div className="flex items-center gap-2 text-xs font-medium text-amber-600 bg-amber-50 px-3 py-1 rounded-full w-fit border border-amber-100 animate-pulse mb-1">
                    <BrainCircuit className="w-3 h-3" />
                    <span>Thinking...</span>
                </div>
            )}

            <div className={`p-5 rounded-2xl ${getModeStyles()} text-sm md:text-base leading-relaxed relative`}>
                <ReactMarkdown 
                    components={{
                        ul: ({node, ...props}) => <ul className="list-disc ml-4 my-2 space-y-1" {...props} />,
                        ol: ({node, ...props}) => <ol className="list-decimal ml-4 my-2 space-y-1" {...props} />,
                        strong: ({node, ...props}) => <strong className="font-semibold" {...props} />,
                        p: ({node, ...props}) => <p className="mb-2 last:mb-0" {...props} />,
                        a: ({node, ...props}) => <a className="text-blue-600 underline hover:text-blue-800" target="_blank" rel="noopener noreferrer" {...props} />,
                    }}
                >
                    {message.text}
                </ReactMarkdown>

                {/* Copy Button */}
                {!isUser && !message.isThinking && (
                    <button 
                        onClick={handleCopy}
                        className={`absolute top-2 right-2 p-1.5 rounded-lg bg-white/80 hover:bg-white text-slate-500 hover:text-blue-600 shadow-sm border border-slate-100 transition-all duration-200 ${copied ? 'opacity-100' : 'opacity-0 group-hover/bubble:opacity-100'}`}
                        title="Copy to clipboard"
                    >
                        {copied ? <Check className="w-3.5 h-3.5 text-green-500" /> : <Copy className="w-3.5 h-3.5" />}
                    </button>
                )}
            </div>

            {/* Research Mode Source Cards */}
            {!isUser && message.mode === ChatMode.RESEARCH && message.groundingMetadata?.searchChunks && message.groundingMetadata.searchChunks.length > 0 && (
                <div className="mt-2 grid grid-cols-1 sm:grid-cols-2 gap-2">
                    {message.groundingMetadata.searchChunks.map((chunk, idx) => {
                        let domain = '';
                        try {
                            domain = new URL(chunk.uri).hostname.replace('www.', '');
                        } catch (e) { domain = 'source'; }

                        return (
                            <a 
                                key={idx} 
                                href={chunk.uri}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="flex flex-col gap-1 p-3 bg-white border border-violet-100 rounded-xl hover:border-violet-300 hover:shadow-md transition-all group/card"
                            >
                                <div className="flex items-start justify-between gap-2">
                                    <span className="text-xs font-bold text-violet-600 uppercase tracking-wide truncate">{domain}</span>
                                    <ExternalLink className="w-3 h-3 text-slate-300 group-hover/card:text-violet-500" />
                                </div>
                                <span className="text-xs text-slate-700 font-medium line-clamp-2 leading-relaxed">
                                    {chunk.title}
                                </span>
                            </a>
                        );
                    })}
                </div>
            )}

            {/* Default / Other Mode Sources (Simple Pills) */}
            {!isUser && message.mode !== ChatMode.RESEARCH && message.groundingMetadata?.searchChunks && message.groundingMetadata.searchChunks.length > 0 && (
                <div className="mt-1 flex flex-wrap gap-2">
                    {message.groundingMetadata.searchChunks.map((chunk, idx) => (
                        <a 
                            key={idx} 
                            href={chunk.uri}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-xs text-slate-500 hover:text-blue-600 hover:border-blue-200 transition-colors shadow-sm"
                        >
                            <Link2 className="w-3 h-3" />
                            <span className="truncate max-w-[150px]">{chunk.title || 'Source'}</span>
                        </a>
                    ))}
                </div>
            )}

            {/* Timestamp */}
            <span className={`text-[10px] text-slate-400 font-medium mt-1 px-1 ${isUser ? 'text-right' : 'text-left'}`}>
                {message.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </span>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ChatInput } from './components/ChatInput';
import { MessageBubble } from './components/MessageBubble';
import { ModeSelector } from './components/ModeSelector';
import { DisclaimerModal } from './components/DisclaimerModal';
import { generateResponse } from './services/geminiService';
import { ChatMode, Message, UserLocation } from './types';
import { Activity, Trash2, Save, CheckCircle, Cloud } from 'lucide-react';

const STORAGE_KEY = 'dr_gemini_chat_history';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [currentMode, setCurrentMode] = useState<ChatMode>(ChatMode.CONSULTATION);
  const [hasAcceptedDisclaimer, setHasAcceptedDisclaimer] = useState(false);
  const [userLocation, setUserLocation] = useState<UserLocation | undefined>(undefined);
  const [showSaveToast, setShowSaveToast] = useState(false);
  const [isAutoSaved, setIsAutoSaved] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Load history from local storage on mount
  useEffect(() => {
    const savedMessages = localStorage.getItem(STORAGE_KEY);
    if (savedMessages) {
        try {
            const parsed = JSON.parse(savedMessages);
            // Convert string timestamps back to Date objects
            const hydrated = parsed.map((m: any) => ({
                ...m,
                timestamp: new Date(m.timestamp)
            }));
            setMessages(hydrated);
        } catch (e) {
            console.error("Failed to load chat history", e);
        }
    }
  }, []);

  // Auto-save history to local storage
  useEffect(() => {
      if (messages.length > 0) {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(messages));

        // Trigger visual auto-save indicator
        setIsAutoSaved(true);
        const timer = setTimeout(() => setIsAutoSaved(false), 2000);
        return () => clearTimeout(timer);
      }
  }, [messages]);

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Get location on mount
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setUserLocation({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
          });
        },
        (error) => {
          console.log("Location access denied or error:", error);
        }
      );
    }
  }, []);

  const clearHistory = () => {
      if (window.confirm("Are you sure you want to clear your medical consultation history?")) {
          setMessages([]);
          localStorage.removeItem(STORAGE_KEY);
      }
  };

  const handleManualSave = () => {
    if (messages.length === 0) return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(messages));
    setShowSaveToast(true);
    setTimeout(() => setShowSaveToast(false), 3000);
  };

  const handleSendMessage = async (text: string) => {
    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      text,
      timestamp: new Date(),
      mode: currentMode,
    };

    setMessages((prev) => [...prev, userMessage]);
    setIsLoading(true);

    try {
      const tempId = (Date.now() + 1).toString();

      if (currentMode === ChatMode.CONSULTATION) {
          setMessages(prev => [...prev, {
              id: tempId,
              role: 'model',
              text: '',
              timestamp: new Date(),
              mode: currentMode,
              isThinking: true
          }]);
      }

      const response = await generateResponse({
        prompt: text,
        history: messages.map(m => ({
          role: m.role,
          parts: [{ text: m.text }]
        })),
        mode: currentMode,
        location: userLocation
      });

      if (currentMode === ChatMode.CONSULTATION) {
          setMessages(prev => prev.map(m => 
              m.id === tempId 
              ? { ...m, text: response.text, isThinking: false, groundingMetadata: response.groundingMetadata }
              : m
          ));
      } else {
          const botMessage: Message = {
            id: Date.now().toString(),
            role: 'model',
            text: response.text,
            timestamp: new Date(),
            mode: currentMode,
            groundingMetadata: response.groundingMetadata
          };
          setMessages((prev) => [...prev, botMessage]);
      }

    } catch (error) {
      console.error(error);
      const errorMessage: Message = {
        id: Date.now().toString(),
        role: 'model',
        text: "I apologize, but I'm having trouble connecting to the medical database. Please try again.",
        timestamp: new Date(),
        mode: currentMode,
      };
      setMessages((prev) => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">

      {!hasAcceptedDisclaimer && (
        <DisclaimerModal onAccept={() => setHasAcceptedDisclaimer(true)} />
      )}

      {/* Toast Notification */}
      <div className={`fixed top-20 right-6 z-50 transform transition-all duration-300 ${showSaveToast ? 'translate-y-0 opacity-100' : '-translate-y-4 opacity-0 pointer-events-none'}`}>
          <div className="bg-emerald-600 text-white px-4 py-2 rounded-lg shadow-lg flex items-center gap-2 font-medium text-sm">
              <CheckCircle className="w-4 h-4" />
              Conversation Saved
          </div>
      </div>

      {/* Header */}
      <header className="bg-white px-6 py-4 border-b border-slate-200 flex items-center justify-between shadow-sm z-20">
        <div className="flex items-center gap-3">
          <div className="bg-blue-600 p-2 rounded-lg text-white">
            <Activity className="w-6 h-6" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">Dr. Gemini</h1>
            <div className="flex items-center gap-2">
               <div className="flex items-center gap-1.5">
                   <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                   <p className="text-xs text-slate-500 font-medium">Dr. G is Online</p>
               </div>

               {/* Auto-save Indicator */}
               <div className={`flex items-center gap-1 transition-opacity duration-500 ${isAutoSaved ? 'opacity-100' : 'opacity-0'}`}>
                   <span className="text-slate-300">|</span>
                   <Cloud className="w-3 h-3 text-slate-400" />
                   <span className="text-[10px] text-slate-400 font-medium">Auto-saved</span>
               </div>
            </div>
          </div>
        </div>

        {messages.length > 0 && (
            <div className="flex items-center gap-1">
                <button 
                    onClick={handleManualSave}
                    className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                    title="Save Chat"
                >
                    <Save className="w-5 h-5" />
                </button>
                <div className="w-px h-6 bg-slate-200 mx-1"></div>
                <button 
                    onClick={clearHistory}
                    className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                    title="Clear Consultation History"
                >
                    <Trash2 className="w-5 h-5" />
                </button>
            </div>
        )}
      </header>

      {/* Mode Selector */}
      <ModeSelector 
        currentMode={currentMode} 
        onModeChange={setCurrentMode} 
        disabled={isLoading} 
      />

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto p-4 md:p-6 scrollbar-hide">
        <div className="max-w-4xl mx-auto min-h-full flex flex-col justify-end">
          {messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center text-center text-slate-400 my-auto py-20 opacity-0 animate-in fade-in slide-in-from-bottom-4 duration-700 fill-mode-forwards">
               <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center mb-6 shadow-sm border border-blue-100">
                 <Activity className="w-10 h-10 text-blue-400" />
               </div>
               <h3 className="text-lg font-semibold text-slate-600 mb-2">Hello, I am Dr. Gemini.</h3>
               <p className="max-w-md mx-auto mb-8">
                 I am here to help. Describe your symptoms, ask about treatments, or find specialists nearby.
               </p>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full max-w-lg">
                   <button onClick={() => handleSendMessage("I have a persistent headache and sensitivity to light.")} className="p-4 bg-white border border-slate-200 rounded-xl hover:border-blue-300 hover:shadow-md transition-all text-sm text-left group">
                       <span className="block font-semibold text-slate-700 mb-1 group-hover:text-blue-600">Symptom Check</span>
                       "I have a headache and sensitivity to light..."
                   </button>
                   <button onClick={() => {
                       setCurrentMode(ChatMode.FIND_CARE);
                       handleSendMessage("Find a cardiologist near me who accepts new patients.");
                   }} className="p-4 bg-white border border-slate-200 rounded-xl hover:border-emerald-300 hover:shadow-md transition-all text-sm text-left group">
                       <span className="block font-semibold text-slate-700 mb-1 group-hover:text-emerald-600">Find a Specialist</span>
                       "Find a cardiologist near me..."
                   </button>
               </div>
            </div>
          ) : (
            messages.map((msg) => (
              <MessageBubble key={msg.id} message={msg} />
            ))
          )}
          <div ref={messagesEndRef} />
        </div>
      </div>

      {/* Input Area */}
      <ChatInput 
        onSendMessage={handleSendMessage} 
        isLoading={isLoading} 
        activeMode={currentMode}
      />

    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { ChatMode, UserLocation } from "../types";

// Initialize the client with the API key from the environment
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION_CONSULTATION = `
You are Dr. AI, a board-certified senior physician with decades of clinical experience.
You are conducting a digital consultation. The user is your patient.

**STRICT PERSONA GUIDELINES:**
1. **IDENTITY**: You are a HUMAN DOCTOR. You are NOT an AI. Do not break character.
   - Never say "As an AI language model".
2. **TONE**: Authoritative, empathetic, professional, and decisive.
3. **METHODOLOGY**:
   - **Step 1: Triage & Data Gathering**: 
     - If the user describes a symptom, YOU MUST ensure you have the following before diagnosing:
       1. **Duration** (How long?)
       2. **Intensity** (You MUST ask specifically: "On a scale of 1-10, how severe is the pain/discomfort?" if not already provided).
     - **CRITICAL RULE**: If the user has NOT provided the intensity on a 1-10 scale, ASK FOR IT IMMEDIATELY in your first response. Do not proceed to diagnosis without this metric.
   - **Step 2: Differential Diagnosis**: Explain likely causes based on the evidence.
   - **Step 3: Management**: specific OTC meds (names/dosages), home care, and "Red Flag" warnings.
   - **Step 4: Referral**: Recommend specialists or ER if needed.

**SAFETY PROTOCOLS:**
- For **LIFE-THREATENING EMERGENCIES** (Chest pain, Stroke signs, Difficulty breathing), COMMAND the user to call 911 immediately.
`;

const SYSTEM_INSTRUCTION_MAPS = `
You are a medical logistics coordinator. Your job is to locate specific healthcare services for the patient.
- If the user asks for "a doctor", ask what kind (e.g., Cardiologist, Dermatologist) if not specified, or assume General Practitioner.
- Extract location data and provide the closest, highest-rated options using Google Maps.
- Be concise.
`;

const SYSTEM_INSTRUCTION_SEARCH = `
You are a medical researcher. Use Google Search to find the latest clinical data, drug interactions, or medical news.
Synthesize the information professionally, citing sources.
`;

interface GenerateResponseParams {
  prompt: string;
  history: { role: string; parts: { text: string }[] }[];
  mode: ChatMode;
  location?: UserLocation;
}

export const generateResponse = async ({
  prompt,
  history,
  mode,
  location,
}: GenerateResponseParams) => {

  let systemInstruction = SYSTEM_INSTRUCTION_CONSULTATION;
  let modelName = 'gemini-3-pro-preview';
  let tools: any[] = [];
  let toolConfig: any = undefined;
  let thinkingConfig: any = undefined;

  // Configure based on Mode
  switch (mode) {
    case ChatMode.CONSULTATION:
      modelName = 'gemini-3-pro-preview';
      systemInstruction = SYSTEM_INSTRUCTION_CONSULTATION;
      // Enable Thinking for complex medical reasoning
      thinkingConfig = { thinkingBudget: 32768 }; 
      break;

    case ChatMode.FIND_CARE:
      modelName = 'gemini-2.5-flash';
      systemInstruction = SYSTEM_INSTRUCTION_MAPS;
      tools = [{ googleMaps: {} }];
      if (location) {
        toolConfig = {
          retrievalConfig: {
            latLng: {
              latitude: location.latitude,
              longitude: location.longitude,
            },
          },
        };
      }
      break;

    case ChatMode.RESEARCH:
      modelName = 'gemini-2.5-flash';
      systemInstruction = SYSTEM_INSTRUCTION_SEARCH;
      tools = [{ googleSearch: {} }];
      break;
  }

  try {
    if (mode === ChatMode.CONSULTATION) {
       // Using Chat API for Consultation to keep context
       const chatHistory = history.map(h => ({
         role: h.role,
         parts: h.parts
       }));

       const chat = ai.chats.create({
         model: modelName,
         config: {
           systemInstruction,
           thinkingConfig,
         },
         history: chatHistory
       });

       const result = await chat.sendMessage({ message: prompt });
       return {
         text: result.text,
         groundingMetadata: undefined 
       };

    } else {
      // For Maps and Search, use generateContent with context injection
      const previousContext = history.map(h => `${h.role}: ${h.parts[0].text}`).join('\n');
      const fullPrompt = `Context of conversation:\n${previousContext}\n\nCurrent User Request: ${prompt}`;

      const result = await ai.models.generateContent({
        model: modelName,
        contents: fullPrompt,
        config: {
          systemInstruction,
          tools,
          toolConfig,
        }
      });

      const text = result.text;
      const groundingMetadata = result.candidates?.[0]?.groundingMetadata;

      let parsedGrounding: any = {};

      if (groundingMetadata?.groundingChunks) {
         const mapChunks = groundingMetadata.groundingChunks
           .filter((c: any) => c.web?.uri && c.web?.title) 
           .map((c: any) => ({ uri: c.web.uri, title: c.web.title }));

         parsedGrounding.searchChunks = mapChunks;
      }

      return {
        text,
        groundingMetadata: parsedGrounding
      };
    }
  } catch (error) {
    console.error("Gemini API Error:", error);
    return {
      text: "I apologize, but I am unable to access my medical database at the moment. Please try again shortly.",
      groundingMetadata: undefined
    };
  }
};

